import assert from "node:assert/strict";
import {createElement} from "react";
import {renderToStaticMarkup} from "react-dom/server";
import type {GeneratedBody} from "../../src/core/generators/definition";
import type {Block} from "../../src/core/types";
import {Legacy2018HeapFigure} from "../../src/ui/Legacy2018HeapFigures";
import {legacy2018HeapReview as r} from "./legacy-2018-pm-heap-review";
import {heapProgramReview as fixed} from "./legacy-2018-pm-heap-figure-review";
import {downHeapReference,isMaxHeap,makeHeapReference} from "./legacy-2018-pm-heap-reference";
const attr=(s:string,k:string)=>{const m=s.match(new RegExp(`(?:^|\\s)${k}="([^"]*)"`));assert(m,`missing ${k}: ${s}`);return m[1];};
const xml=(s:string)=>s.replaceAll("&lt;","<").replaceAll("&gt;",">").replaceAll("&amp;","&").replaceAll("&quot;",'"').replaceAll("&#x27;","'");
const group=(svg:string,key:string,value:string)=>{const m=svg.match(new RegExp(`<g ${key}="${value}"[^>]*>([\\s\\S]*?)</g>`));assert(m,`${key}=${value}`);return m[1];};
const texts=(s:string)=>[...s.matchAll(/<text\b([^>]*)>([^<]*)<\/text>/g)].map(m=>({text:xml(m[2]),x:Number(attr(m[1],"x")),y:Number(attr(m[1],"y")),raw:m[1]}));
const numbers=(s:string,names:string[])=>names.map(k=>Number(attr(s,k)));
export function heapSvg(block:Block){assert(block.type==="diagram"&&block.scene.kind==="source_figure");return renderToStaticMarkup(createElement(Legacy2018HeapFigure,{profile:block.scene.profile,values:block.scene.values,caption:block.caption??""}));}
/** Read serialized shapes, wire endpoints, values and visible text. Data IDs
 * locate the elements but do not supply edges, code or numeric answers. */
export function readHeapTree(svg:string){const values=fixed.treePoints.map(([x,y],i)=>{const g=group(svg,"data-heap-node",String(i)),circle=g.match(/<circle\b([^>]*)/)!,t=texts(g);assert.deepEqual(numbers(circle[1],["cx","cy","r"]),[x,y,42]);assert.equal(t.length,1);assert.deepEqual([t[0].x,t[0].y],[x,y]);assert.equal(attr(t[0].raw,"text-anchor"),"middle");assert.match(t[0].text,/^\d+$/);return Number(t[0].text);});const lines=[...svg.matchAll(/<line data-parent-edge="\d+"([^>]*)/g)];assert.equal(lines.length,6);const edges=lines.map(m=>{const a=numbers(m[1],["x1","y1"]),b=numbers(m[1],["x2","y2"]),from=fixed.treePoints.findIndex(p=>p[0]===a[0]&&p[1]===a[1]),to=fixed.treePoints.findIndex(p=>p[0]===b[0]&&p[1]===b[1]);assert(from>=0&&to>=0);return[from,to];});assert.deepEqual(edges,fixed.treeEdges);assert.deepEqual(texts(svg).slice(-3).map(t=>[t.text,t.x,t.y]),[["根",430,18],["左側の子",220,118],["右側の子",640,118]]);assert.deepEqual(values.slice().sort((a,b)=>a-b),[5,10,15,20,30,45,60]);assert(isMaxHeap(values));return values;}
function marker(svg:string,reference:string){const id=reference.match(/^url\(#(.+)\)$/)?.[1];assert(id);const m=svg.match(new RegExp(`<marker id="${id.replace(/[.*+?^${}()|[\]\\]/g,"\\$&")}"([^>]*)>([\\s\\S]*?)</marker>`));assert(m,"actual marker exists");assert.deepEqual(numbers(m[1],["markerWidth","markerHeight","refX","refY"]),[10,10,10,5]);assert.equal(attr(m[1],"orient"),"auto");assert.equal(attr(m[1],"markerUnits"),"userSpaceOnUse");const path=m[2].match(/<path\b([^>]*)/)!;assert.equal(attr(path[1],"d"),"M0 0 L10 5 L0 10 Z");assert.equal(attr(path[1],"fill"),"currentColor");}
export function readHeapArray(svg:string){const f=fixed.array,values=Array.from({length:7},(_,i)=>{const g=group(svg,"data-array-cell",String(i)),rect=g.match(/<rect\b([^>]*)/)!,t=texts(g);assert.deepEqual(numbers(rect[1],["x","y","width","height"]),[f.left+i*f.width,f.top,f.width,f.height]);assert.deepEqual(t.map(t=>[t.x,t.y]),[[f.left+(i+.5)*f.width,f.indexY],[f.left+(i+.5)*f.width,f.valueY]]);assert.equal(t[0].text,String(i));assert.match(t[1].text,/^\d+$/);return Number(t[1].text);});for(const[i,[parent,child]]of fixed.treeEdges.entries()){const g=group(svg,"data-array-edge",String(child)),circle=g.match(/<circle\b([^>]*)/)!,line=g.match(/<polyline\b([^>]*)/)!;const from=f.left+(parent+.5)*f.width,to=f.left+(child+.5)*f.width;assert.deepEqual(numbers(circle[1],["cx","cy","r"]),[from,120,4]);assert.equal(attr(line[1],"points"),`${from},120 ${from},${f.edgeY[i]} ${to},${f.edgeY[i]} ${to},120`);marker(svg,attr(line[1],"marker-end"));}assert.deepEqual(texts(svg).slice(0,2).map(t=>[t.text,t.x,t.y]),[["要素番号",95,45],["heap",95,95]]);assert.deepEqual(values.slice().sort((a,b)=>a-b),[5,10,15,20,30,45,60]);assert(isMaxHeap(values));return values;}
export function readHeapProgram(svg:string,which:"one"|"two"){const wanted=fixed[which],actual=[...svg.matchAll(/<g data-statement="([^"]+)"[^>]*>([\s\S]*?)<\/g>/g)].map(m=>{const t=texts(m[2]).at(-1)!;if(m[1].startsWith("blank-"))assert.equal(attr(t.raw,"text-anchor"),"middle");return[m[1],t.x,t.y,t.text];});assert.deepEqual(actual,wanted);const controls=[...svg.matchAll(/<g data-control="([^"]+)" data-kind="([^"]+)"[^>]*>([\s\S]*?)<\/g>/g)];assert.equal(controls.length,fixed.controls[which].length);for(const[i,m]of controls.entries()){const[name,kind,x,top,bottom,otherwise]=fixed.controls[which][i];assert.equal(m[1],name);assert.equal(m[2],kind);const lines=[...m[3].matchAll(/<line\b([^>]*)/g)].map(m=>numbers(m[1],["x1","y1","x2","y2"]));assert.deepEqual(lines,[[x,top+5,x,bottom-5],...(otherwise===null?[]:[[x,otherwise,x+20,otherwise]])]);if(kind==="loop"){assert(!m[3].includes("<polygon"));assert.deepEqual([...m[3].matchAll(/<rect\b([^>]*)/g)].map(m=>numbers(m[1],["x","y","width","height"])),[[x-5,top-5,10,10],[x-5,bottom-5,10,10]]);}else{assert(!m[3].includes("<rect"));const triangles=[...m[3].matchAll(/<polygon\b([^>]*)/g)];assert.deepEqual(triangles.map(m=>attr(m[1],"points")),[`${x-6},${top+5} ${x},${top-6} ${x+6},${top+5}`,`${x-6},${bottom-5} ${x},${bottom+6} ${x+6},${bottom-5}`]);for(const t of triangles)assert.equal(attr(t[1],"style"),"fill:currentColor");}}
 if(which==="one"){const blanks=[...svg.matchAll(/<rect data-blank="([^"]+)"([^>]*)/g)].map(m=>[m[1],...numbers(m[2],["x","y","width","height"])]);assert.deepEqual(blanks,[["a",98,237,90,35],["b",333,273,56,35]]);}else{assert.deepEqual([...svg.matchAll(/<text data-line="(\d+)"([^>]*)>(\d+)<\/text>/g)].map(m=>{assert.equal(m[1],m[3]);assert.equal(Number(attr(m[2],"x")),20);return[Number(m[3]),Number(attr(m[2],"y"))];}),fixed.programTwoLineNumbers);const a=svg.match(/<line data-alpha="true"([^>]*)/)!;assert.deepEqual(numbers(a[1],["x1","y1","x2","y2"]),[800,134,650,134]);marker(svg,attr(a[1],"marker-end"));}
 return actual;
}
export function readHeapRegions(svg:string){const f=fixed.regions;assert.deepEqual(texts(svg).slice(2,10).map(t=>t.text),f.labels);for(let i=0;i<8;i++){const g=group(svg,"data-region-cell",String(i)),rect=g.match(/<rect\b([^>]*)/)!,t=texts(g);assert.deepEqual(numbers(rect[1],["x","y","width","height"]),[f.left+i*f.width,f.top,f.width,f.height]);assert.deepEqual([t[0].x,t[0].y],[f.left+(i+.5)*f.width,45]);}for(const[key,points]of[["data-last-pointer",[655,180,655,120]],["data-target-range",[710,150,160,150]],["data-sorted-range",[710,150,1040,150]]] as const){const line=svg.match(new RegExp(`<line ${key}="true"([^>]*)`))!;assert(line);assert.deepEqual(numbers(line[1],["x1","y1","x2","y2"]),points);marker(svg,attr(line[1],"marker-end"));}assert.deepEqual(texts(svg).slice(-3).map(t=>[t.text,t.x,t.y]),[["last",655,201],["整列対象領域",400,240],["整列済みデータ領域",875,240]]);}
export function legacy2018HeapOracle(source:string,b:GeneratedBody,v:number[]){assert.equal(source,r.source);assert.equal(v.length,2);assert(Number.isInteger(v[0])&&v[0]>=0&&v[0]<2&&Number.isInteger(v[1])&&v[1]>=0&&v[1]<24);const prose=b.prompt.map(p=>p.type==="paragraph"?p.text:"").join("\n");for(const re of[/昇順に整列/,/親は一つ又は二つ/,/常に大きいか等しい/,/丸は節/,/配列の要素番号は、0から/,/hnum > 0/,/heap\[0\]は、根/,/heap\[2×i\+1\]/,/heap\[2×i\+2\]/,/子が一つの場合、左側の子/,/\(i−1\)÷2（小数点以下切捨て）/,/lastの値はhnum−1/,/行番号3の実行が終了した直後のα/,/行番号4から行番号7までの1回目/,/行番号5.*swap.*直後/,/行番号15.*最初にnに代入/,/右側の子の値が左側の子の値［d］/,/tmpを次のnとして\(2\)に戻る/])assert.match(prose,re);const diagrams=b.prompt.filter((p):p is Extract<Block,{type:"diagram"}>=>p.type==="diagram");assert.equal(diagrams.length,5);const suffixes=["tree","array","program-one","regions","program-two"];for(const[d,i]of diagrams.map((d,i)=>[d,i] as const)){assert(d.scene.kind==="source_figure");assert.equal(d.scene.profile,`legacy-2018-heap-${suffixes[i]}`);assert.deepEqual(d.scene.values,v);}
 const heap=readHeapTree(heapSvg(diagrams[0]));assert.deepEqual(heap.toString(),readHeapArray(heapSvg(diagrams[1])).toString());assert.deepEqual(heap.slice().sort((a,b)=>a-b),[5,10,15,20,30,45,60]);assert(isMaxHeap(heap));assert.deepEqual(heap.slice(0,3),v[0]?[60,45,30]:[60,30,45]);const permutations:number[][]=[];function perm(prefix:number[],rest:number[]){if(!rest.length){permutations.push(prefix);return;}for(let i=0;i<rest.length;i++)perm([...prefix,rest[i]],rest.filter((_,j)=>i!==j));}perm([],[5,10,15,20]);assert.deepEqual(heap.slice(3),permutations[v[1]]);assert.deepEqual(makeHeapReference(heap),heap);readHeapProgram(heapSvg(diagrams[2]),"one");readHeapRegions(heapSvg(diagrams[3]));readHeapProgram(heapSvg(diagrams[4]),"two");
 const tables=b.prompt.filter(p=>p.type==="table");assert.deepEqual(tables.map(t=>({caption:t.caption,columns:t.columns,rows:t.rows})),r.sourceTables);assert.equal(b.choices.length,24);const choiceTexts=b.choices.map(c=>{assert.equal(c.length,1);assert(c[0].type==="paragraph");return c[0].text;}),expected=r.originalChoices.flat();assert.deepEqual(choiceTexts,expected);assert.equal(b.answerParts?.length,5);assert.equal(b.partAnswers?.length,5);assert.equal(b.correctIndex,undefined);const counts=[6,4,4,4,6],offsets=[0,6,10,14,18];for(let i=0;i<5;i++){assert.deepEqual(b.answerParts![i],{id:`part-${"abcde"[i]}`,label:r.labels[i],choiceIds:Array.from({length:counts[i]},(_,j)=>`choice-value-${offsets[i]+j+1}`)});}
 const work=heap.slice();[work[0],work[6]]=[work[6],work[0]];const c=choiceTexts.slice(10,14).findIndex(t=>Number(t)===work[0]),steps=downHeapReference(work,5),first=steps.find(s=>s.swapped)!;assert(first);const e=choiceTexts.slice(18).findIndex(t=>Number(t)===first.chosen),answers=[1,3,c,1,e];assert.deepEqual(b.partAnswers,answers.map((answer,i)=>({kind:"choice",partId:`part-${"abcde"[i]}`,choiceId:`choice-value-${offsets[i]+answer+1}`})));assert.equal(c>=0&&e>=0,true);for(const re of[/heap\[k\] > heap\[parent\(k\)\]/,/同値のときも右子/,/hlast以下/,/last=1/,/hnum>0/])assert.match(b.explanation,re);assert(b.explanation.includes(`末尾の${heap[6]}がheap[0]へ移り`));assert(b.explanation.includes(`行15でnに${first.chosen}を最初に代入`));assert(!/[アイウエオカ]が正答|[アイウエオカ]が公式/.test(b.explanation));assert.deepEqual(b.contexts?.[0].blocks.map(p=>{assert(p.type==="image");return p.assetId;}),["asset-ipa-2018h30h-fe-pm-8-common-p4","asset-ipa-2018h30h-fe-pm-8-common-p5"]);return{heap,firstN:first.chosen,rootAfterSwap:heap[6],answers,steps};
}
